                        }

                        if ($ConditionValue -eq "*") {

                            $BroadExclusion = $true
                        }

                        if (
                            $ConditionType -match
                            "(?i)^is any$"
                        ) {

                            $BroadExclusion = $true
                        }

                        if ($BroadExclusion) {

                            $Conflicts += (
                                "EID $EventId / $EventType has a broad " +
                                "exclude rule that may suppress security-relevant activity."
                            )
                        }
                    }
                }
            }
        }
    }

    return [PSCustomObject]@{
        filters = @(
            $FilterInventory
        )

        conflicts = @(
            $Conflicts |
            Sort-Object -Unique
        )
    }
}

